// Quiz-Repo. 🔴 Wer eine Sprache wieder abschaltet, nimmt sie NUR hier heraus;
// die Vorlagen bleiben stehen und lassen sich jederzeit wieder zuschalten.
const SUPPORTED_LANGS = ['de', 'it', 'en', 'hu', 'fr', 'ru'];
