const selected = $('Code - Select Email ID').item.json;
const inputItems = $input.all();
let rows = [];
for (const item of inputItems) {
  if (Array.isArray(item.json)) rows.push(...item.json);
  else if (item.json && item.json.session_hash) rows.push(item.json);
}
const session = rows.find(r => r && r.session_hash);
return { json: {
  ...selected,
  skip: false,
  sessionHash: session?.session_hash || '',
  resumeTargetRequest: ['d1', 'd2'].includes(selected.phase) ? 'final' : 'videos',
}};

const selected = $('Code - Build Resume Request').item.json;
const generated = $json || {};
const resumeUrl = generated.shortUrl || generated.resumeUrl || '';
const target = generated.resumeTarget || '';
const step = Number(generated.lastVideoStep || 0);
const expectedStepByPhase = { a2: 1, a3: 1, b1: 2, b2: 2, c1: 3, c2: 3, d1: 3, d2: 3 };
const expectedStep = expectedStepByPhase[selected.phase] || 1;

const skip = (reason, extra = {}) => ({ json: {
  ...selected,
  ...extra,
  skip: true,
  reason,
  phase: selected.phase,
  lead_hash: selected.lead_hash,
}});

if (!generated.success || !resumeUrl) {
  return skip('resume_link_generation_failed', { bridge_error: generated.error || null });
}

if (resumeUrl.length > 190) {
  return skip('resume_link_too_long', {
    resumeUrlLength: resumeUrl.length,
    generatedShortKey: generated.shortKey || null,
    generatedShortUrl: generated.shortUrl || null,
  });
}

if (selected.phase === 'd1' || selected.phase === 'd2') {
  if (target !== 'final' || step !== 3) {
    return skip('resume_target_mismatch', { generatedResumeTarget: target, generatedLastVideoStep: step, expectedResumeTarget: 'final', expectedLastVideoStep: 3 });
  }
} else {
  if (target !== 'videos' || step < expectedStep) {
    return skip('resume_target_mismatch', { generatedResumeTarget: target, generatedLastVideoStep: step, expectedResumeTarget: 'videos', expectedLastVideoStep: expectedStep });
  }
}

return { json: {
  ...selected,
  skip: false,
  resumeUrl,
  generatedResumeTarget: target,
  generatedLastVideoStep: step,
}};

const item = $json || {};
if (item.skip) return { json: item };

// 🔴 Seit 26.08.2026 gilt die Bremse fuer ALLE Phasen, nicht nur die Zweitmails.
// Grund: Die stille Zeilengrenze der Auswahlabfrage hatte 186 Menschen drei Wochen lang
// unsichtbar gemacht. Nach der Reparatur waeren sie alle in EINEM Lauf angeschrieben
// worden - ein Schwall, der Zustellbarkeit und Ruf kostet. Bei 25 je Lauf und zwoelf
// Laeufen taeglich ist ein solcher Rueckstand binnen eines Tages abgearbeitet.
const SECOND_PHASES = ['a3', 'b2', 'c2', 'd2'];
const ALLE_PHASEN = ['a2', 'b1', 'c1', 'd1', 'a3', 'b2', 'c2', 'd2'];
if (!ALLE_PHASEN.includes(item.phase)) return { json: item };

const executionId = String($execution.id || '');
if (!executionId) throw new Error('Missing n8n execution id for recovery cap');

const state = $getWorkflowStaticData('global');
if (!state.nurtureRecoveryCap || state.nurtureRecoveryCap.executionId !== executionId) {
  state.nurtureRecoveryCap = {
    executionId,
    counts: Object.fromEntries(ALLE_PHASEN.map(phase => [phase, 0])),
  };
}

// 🔴 Zusaetzlich eine GLOBALE Obergrenze je Lauf. Die Zaehlung je Phase allein liess
// theoretisch 4x25 + 4x20 = 180 Mails in einem Lauf zu - genau der Schwall, der verhindert
// werden sollte. Gemessen am 26.08. im ersten reparierten Lauf: 63 Mails, davon a2 und b1
// mit exakt 25 an ihrer Phasengrenze.
// 🔴 Am 28.08.2026 fuer den Umbau auf die Plattform-DB auf 5 gedrosselt und am selben
  // Abend wieder auf 60 geoeffnet (Entscheidung Markus). Belegt VOR dem Oeffnen: vier Laeufe
  // (06:01, 14:03, 16:03, 18:00 MESZ), zwoelf Mails, kein Fehlereintrag, bei Postmark null
  // Bounces und zwei Oeffnungen. 60 war auch der Wert vor der Umstellung.
  // Es warteten zu diesem Zeitpunkt rund 195 faellige Menschen hinter der Bremse.
  const GESAMT_GRENZE = 60;
state.nurtureRecoveryCap.gesamt = Number(state.nurtureRecoveryCap.gesamt || 0);
if (state.nurtureRecoveryCap.gesamt >= GESAMT_GRENZE) {
  return { json: { ...item, skip: true, reason: 'gesamt_cap_reached' } };
}

const count = Number(state.nurtureRecoveryCap.counts[item.phase] || 0);
const GRENZE = SECOND_PHASES.includes(item.phase) ? 20 : 25;
if (count >= GRENZE) {
  return { json: { ...item, skip: true, reason: 'recovery_cap_reached' } };
}
state.nurtureRecoveryCap.counts[item.phase] = count + 1;
state.nurtureRecoveryCap.gesamt += 1;
return { json: item };

